if [ -n "${XDG_RUNTIME_DIR-}" ] && [ -n "${DBUS_SESSION_BUS_ADDRESS-}" ] && { grep -qs __bsl_agent_ /etc/profile.d/breadstick-vm.sh /etc/bashrc /etc/profile.d/breadstick-terminal.sh || grep -qx "BSL_SESSION_USER=$(id -un)" /run/bsl/session 2>/dev/null; }; then export __bsl_session_vars="XDG_RUNTIME_DIR DBUS_SESSION_BUS_ADDRESS" __bsl_v_XDG_RUNTIME_DIR="$XDG_RUNTIME_DIR" __bsl_v_DBUS_SESSION_BUS_ADDRESS="$DBUS_SESSION_BUS_ADDRESS" __bsl_agent_XDG_RUNTIME_DIR="$XDG_RUNTIME_DIR" __bsl_agent_DBUS_SESSION_BUS_ADDRESS="$DBUS_SESSION_BUS_ADDRESS"; fi; if command -v tmux >/dev/null 2>&1; then { [ -S /tmp/.breadstick-tmux-$(id -u)-q1 ] && ! tmux -S /tmp/.breadstick-tmux-$(id -u)-q1 list-sessions >/dev/null 2>&1 && rm -f /tmp/.breadstick-tmux-$(id -u)-q1; } 2>/dev/null; BSLCONF=; BSLMOUSE=; [ -f "$HOME/.tmux.conf" ] || { BSLMOUSE='; set-option -g mouse on'; [ -f /etc/breadstick/tmux.conf ] && BSLCONF='-f /etc/breadstick/tmux.conf'; }; exec tmux $BSLCONF -S /tmp/.breadstick-tmux-$(id -u)-q1 -u new-session -A -s main $BSLMOUSE; else exec "$(getent passwd "$(id -un)" | cut -d: -f7)" -l; fi
